import{_ as l,o as i,c as s,a3 as t,j as a,a as n}from"./chunks/framework.BP2ycr77.js";const q=JSON.parse('{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","description":"","frontmatter":{"title":"Évaluation 2 — Rapport de faisabilité technique : proposition technique","aside":false},"headers":[],"relativePath":"evaluations/evaluation-2.md","filePath":"evaluations/evaluation-2.md"}'),r={name:"evaluations/evaluation-2.md"},o={class:"info custom-block"},u={style:{"overflow-x":"auto"}},c={class:"schema-exemple",style:{"min-width":"540px",display:"block"},viewBox:"0 0 700 230",role:"img","aria-label":"Schéma : le site envoie la commande à l'outil de commande, qui envoie le paiement au terminal et le courriel de confirmation au client. La liste de production est imprimée à la main."};function d(p,e,g,h,m,x){return i(),s("div",null,[e[3]||(e[3]=t('<h1 id="evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" tabindex="-1">Évaluation 2 — Rapport de faisabilité technique : proposition technique <a class="header-anchor" href="#evaluation-2-—-rapport-de-faisabilite-technique-proposition-technique" aria-label="Permalink to &quot;Évaluation 2 — Rapport de faisabilité technique : proposition technique&quot;">​</a></h1><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>En bref</strong><br><ul class="list-disc pl-5"><li><strong>Pondération :</strong> 20 % de la note finale, dont 10 % de l&#39;évaluation pour la qualité du français.</li><li><strong>Équipe :</strong> votre équipe de la session, 2 ou 3 personnes.</li><li><strong>Remise :</strong> sur LÉA, au plus tard le <strong>mercredi 9 décembre, 18 h 30</strong> (début de la séance 11).</li><li><strong>Format :</strong> le rapport <strong>complet</strong> (parties 1 et 2) dans un seul fichier Word (<code>.docx</code>) nommé <code>eval2-equipeN-nom1-nom2-nom3.docx</code>.</li><li><strong>Longueur :</strong> de 8 à 12 pages pour la partie 2, sans compter les annexes.</li><li><strong>Retard :</strong> 10 % par jour; aucun travail accepté après 7 jours.</li></ul><a href="./../fiches/eval2-gabarit-proposition.docx" download><strong>Télécharger le gabarit de la partie 2 (Word)</strong></a></div><hr><h2 id="la-mise-en-situation" tabindex="-1">La mise en situation <a class="header-anchor" href="#la-mise-en-situation" aria-label="Permalink to &quot;La mise en situation&quot;">​</a></h2><p>Votre évaluation technique a fait le portrait du projet d&#39;<a href="./../mandat/">Aventure Saint-Maurice</a> : ce qu&#39;il exige, ce qui le contraint, ce qui pourrait mal tourner et les technologies qui existent. Mélanie l&#39;a lue. Sa question, maintenant, est simple :</p><blockquote><p>« Qu&#39;est-ce que vous nous conseillez, combien ça coûte, et est-ce que ce sera prêt pour le 1<sup>er</sup> mars ? »</p></blockquote><p>La <strong>proposition technique</strong> y répond. Elle complète le même document : c&#39;est la <strong>deuxième moitié</strong> du rapport de faisabilité.</p><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Cette fois, vous tranchez.</strong><br> La partie 1 décrivait sans recommander. La partie 2 <strong>choisit</strong> : un outil par question, des formats, des adaptations, un échéancier, un devis et une recommandation finale. Chaque choix s&#39;appuie sur ce que la partie 1 a établi : une exigence, une contrainte, un risque, un essai ou une source. Un choix qui ne renvoie à rien de tout cela est une opinion. </div><hr><h2 id="competence-et-elements-vises" tabindex="-1">Compétence et éléments visés <a class="header-anchor" href="#competence-et-elements-vises" aria-label="Permalink to &quot;Compétence et éléments visés&quot;">​</a></h2><p><strong>HK29 — Évaluer la faisabilité technique d&#39;un projet</strong></p><ul><li>Élément 4 : proposer des moyens techniques.</li><li>Élément 5 : rédiger un rapport de faisabilité technique (seconde partie).</li></ul><hr><h2 id="le-lecteur" tabindex="-1">Le lecteur <a class="header-anchor" href="#le-lecteur" aria-label="Permalink to &quot;Le lecteur&quot;">​</a></h2><p>Toujours <strong>Mélanie Gauthier</strong>, avec Patrick Lavoie. Mêmes règles qu&#39;à l&#39;évaluation 1 : chaque terme technique est expliqué la première fois ou évité, les tableaux résument et le texte dit ce qu&#39;ils veulent dire pour l&#39;entreprise.</p><p>Une nouveauté : Mélanie va <strong>prendre des décisions</strong> à partir de ce rapport. Ce qu&#39;elle doit décider et faire doit donc être écrit noir sur blanc, avec des dates.</p><hr><h2 id="le-contenu-du-rapport" tabindex="-1">Le contenu du rapport <a class="header-anchor" href="#le-contenu-du-rapport" aria-label="Permalink to &quot;Le contenu du rapport&quot;">​</a></h2><h3 id="ce-qui-change-dans-la-partie-1" tabindex="-1">Ce qui change dans la partie 1 <a class="header-anchor" href="#ce-qui-change-dans-la-partie-1" aria-label="Permalink to &quot;Ce qui change dans la partie 1&quot;">​</a></h3><ul><li><strong>La page de titre</strong> : « Rapport de faisabilité technique », sans « Partie 1 », avec la nouvelle date.</li><li><strong>Le résumé</strong> est réécrit pour tout le rapport. Il donne maintenant la <strong>recommandation</strong>, le coût et la date de mise en ligne visée. Toujours une demi-page au maximum.</li><li><strong>La portée (2.3)</strong> : le rapport couvre maintenant aussi les choix, les coûts et l&#39;échéancier.</li><li><strong>Les commentaires</strong> reçus pour l&#39;évaluation 1 sont appliqués dans les sections 1 à 7.</li><li><strong>La section 7</strong> : les questions qui ont reçu une réponse lors de la rencontre avec le client (séance 9) sont marquées comme telles, avec la réponse.</li></ul><h3 id="les-nouvelles-sections" tabindex="-1">Les nouvelles sections <a class="header-anchor" href="#les-nouvelles-sections" aria-label="Permalink to &quot;Les nouvelles sections&quot;">​</a></h3><p>Le gabarit de la partie 2 contient ces sections, avec des consignes dans chacune. Copiez-les dans votre rapport, entre la section 7 et les références.</p><h4 id="_8-les-choix-techniques" tabindex="-1">8. Les choix techniques <a class="header-anchor" href="#_8-les-choix-techniques" aria-label="Permalink to &quot;8. Les choix techniques&quot;">​</a></h4><ul><li><strong>8.1 Les critères de choix</strong> : ce qui compte le plus pour ce client, tiré de vos exigences et de vos contraintes, avec un poids pour chacun (par exemple : Mélanie peut modifier les prix seule, le coût annuel, la gestion des départs à 8 places).</li><li><strong>8.2 Les choix pour les cinq questions</strong> : pour chacune des questions Q1 à Q5, l&#39;outil ou la solution retenu, <strong>pourquoi</strong> (les critères, vos essais, vos sources), ce que vous écartez et pourquoi, et ce qui reste à vérifier. Votre question peut s&#39;appuyer sur vos essais; pour les quatre autres, dites sur quoi repose le choix, et ce qu&#39;un essai devra confirmer avant de s&#39;engager. Pour Q4, on choisit <strong>où héberger et comment diffuser</strong> les vidéos; la préparation des fichiers va à la section 9.</li><li><strong>8.3 Comment les outils fonctionnent ensemble</strong> : un schéma simple qui montre le site, la réservation, la décharge, Square, Viator, les courriels et le nom de domaine, et ce qui passe de l&#39;un à l&#39;autre. Les liens qui ne fonctionnent pas, ou qui demandent une manipulation à la main, y sont indiqués.</li></ul>',24)),a("div",o,[e[1]||(e[1]=t('<p class="custom-block-title">Un exemple, sur un autre client</p><p>Une boulangerie veut prendre les commandes du samedi en ligne. Voici à quoi ressemblent ses critères et son schéma. Les outils sont inventés.</p><table><thead><tr><th>Critère</th><th>D&#39;où il vient</th><th>Poids</th></tr></thead><tbody><tr><td>La propriétaire change le menu seule, chaque vendredi</td><td>Exigence : « le menu change toutes les semaines »</td><td>3</td></tr><tr><td>Le paiement passe par son terminal actuel</td><td>Contrainte technologique : elle garde son terminal</td><td>2</td></tr><tr><td>Moins de 40 $ par mois</td><td>Contrainte de budget</td><td>2</td></tr><tr><td>Un rappel par texto la veille</td><td>Exigence souhaitée : « les clients oublient »</td><td>1</td></tr></tbody></table><p><strong>Comment les poids servent.</strong> Un outil qui échoue à un critère de poids 3 est écarté, même s&#39;il gagne partout ailleurs. Entre les outils qui restent, les critères de poids 2 tranchent; ceux de poids 1 départagent seulement les égalités. Dans la section 8.2, nommez les critères qui ont décidé.</p>',4)),a("div",u,[(i(),s("svg",c,[...e[0]||(e[0]=[t('<defs><marker id="fl" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="currentColor"></path></marker></defs><g fill="none" stroke="currentColor" stroke-width="1.5"><rect x="5" y="20" width="170" height="50" rx="8"></rect><rect x="265" y="20" width="170" height="50" rx="8"></rect><rect x="525" y="20" width="170" height="50" rx="8"></rect><rect x="265" y="170" width="170" height="50" rx="8"></rect><rect x="525" y="170" width="170" height="50" rx="8"></rect><path d="M175,45 H261" marker-end="url(#fl)"></path><path d="M435,45 H521" marker-end="url(#fl)"></path><path d="M435,66 L560,166" marker-end="url(#fl)"></path><path d="M350,70 V166" stroke-dasharray="6 5" marker-end="url(#fl)"></path></g><g fill="currentColor" font-size="14" text-anchor="middle"><text x="90" y="50">Site de la boulangerie</text><text x="350" y="50">Outil de commande</text><text x="610" y="50">Terminal de paiement</text><text x="350" y="200">Liste de production</text><text x="610" y="200">Client</text><g font-size="12"><text x="218" y="36">la commande</text><text x="478" y="36">le paiement</text><text x="508" y="112" text-anchor="start">courriel de</text><text x="508" y="127" text-anchor="start">confirmation</text><text x="340" y="112" text-anchor="end">imprimée à la main,</text><text x="340" y="127" text-anchor="end">le vendredi soir</text></g></g>',3)])]))]),e[2]||(e[2]=a("p",null,[n("Une boîte par outil, une flèche par chose qui passe d'un outil à l'autre, nommée sur la flèche. La flèche en pointillé est une "),a("strong",null,"manipulation à la main"),n(" : quelqu'un devra la faire chaque semaine. C'est souvent là que se cachent les erreurs et le temps perdu.")],-1))]),e[4]||(e[4]=t('<h4 id="_9-les-formats-et-les-regles-de-mise-en-ligne" tabindex="-1">9. Les formats et les règles de mise en ligne <a class="header-anchor" href="#_9-les-formats-et-les-regles-de-mise-en-ligne" aria-label="Permalink to &quot;9. Les formats et les règles de mise en ligne&quot;">​</a></h4><ul><li><strong>9.1 Les règles par sorte de contenu</strong> : un tableau qui donne, pour chaque sorte de contenu, le format, la largeur, le poids maximal, l&#39;outil et la règle d&#39;accessibilité à respecter. (Vu à la séance 7 et au Lab 07.)</li><li><strong>9.2 Qui fait ce travail chez le client</strong> : qui, avec quel outil, et combien de temps ça lui prendra.</li></ul><h4 id="_10-les-adaptations-proposees" tabindex="-1">10. Les adaptations proposées <a class="header-anchor" href="#_10-les-adaptations-proposees" aria-label="Permalink to &quot;10. Les adaptations proposées&quot;">​</a></h4><ul><li><strong>10.1</strong> Pour chaque <strong>contrainte déterminante</strong> (section 4.3) et chaque <strong>risque de la zone rouge</strong> (section 5.3) : l&#39;adaptation que vous proposez et ce qu&#39;elle change pour le client. Exemple : le réseau est faible au quai, donc la liste des participants et de leurs allergies doit pouvoir s&#39;ouvrir sans connexion.</li><li><strong>10.2 Ce que vous ne proposez pas</strong> (l&#39;application mobile, le niveau de la rivière en direct, l&#39;ouverture l&#39;hiver…), et pourquoi, ou pour quand.</li></ul><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Une mesure, une adaptation : quelle différence ?</strong><br> Ne recopiez pas la section 5.3. La <strong>mesure</strong> de l&#39;évaluation 1 disait ce qu&#39;il faut obtenir pour réduire le risque, sans choisir d&#39;outil : « la liste des participants doit rester consultable sans réseau ». L&#39;<strong>adaptation</strong> est la décision concrète de votre proposition qui obtient ce résultat : l&#39;outil retenu, la fonction à activer ou la façon de faire. Par exemple : « on active la liste hors ligne de l&#39;outil retenu à la section 8.2, et Patrick l&#39;ouvre au chalet avant chaque départ ». Renvoyez à la mesure par son numéro. </div><h4 id="_11-le-temps" tabindex="-1">11. Le temps <a class="header-anchor" href="#_11-le-temps" aria-label="Permalink to &quot;11. Le temps&quot;">​</a></h4><ul><li><strong>11.1 Les tâches et l&#39;estimation</strong> : le travail découpé en tâches, chacune estimée en trois chiffres (optimiste, probable, pessimiste), et l&#39;estimation retenue. (Vu à la séance 8.)</li><li><strong>11.2 L&#39;échéancier</strong> : un échéancier <strong>simple, par étapes</strong>, jusqu&#39;au 1<sup>er</sup> mars 2027 : ce qui est livré à chacune, ce que le client doit fournir et quand, et le <strong>coussin</strong> prévu pour les imprévus. (Vu à la séance 8.) Les cycles de travail agiles viendront aux séances 16 et 17; ils ne sont pas demandés ici.</li></ul><h4 id="_12-l-argent" tabindex="-1">12. L&#39;argent <a class="header-anchor" href="#_12-l-argent" aria-label="Permalink to &quot;12. L&#39;argent&quot;">​</a></h4><ul><li><strong>12.1 Les coûts uniques</strong> : la construction (les heures de l&#39;estimation × le taux de Studio Web FC) et ce qui s&#39;achète une seule fois.</li><li><strong>12.2 Les coûts annuels</strong> : les abonnements, le nom de domaine, les commissions, l&#39;entretien.</li><li><strong>12.3 Le total sur trois ans, comparé au budget</strong> : voir l&#39;encadré ci-dessous.</li><li><strong>12.4 Trois façons d&#39;entrer dans le budget</strong> : enlever des fonctionnalités, changer d&#39;outil, ou livrer le site en plusieurs étapes, avec ce que chacune fait économiser et ce que le client perd. (Vu à la séance 8.)</li></ul><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>À quoi comparer les coûts</strong><ul class="list-disc pl-5"><li>Le budget de Mélanie, <strong>8 000 $</strong> (ou <strong>13 000 $</strong> si la subvention de la MRC est accordée), sert à la <strong>construction</strong> (document 3 du mandat). Comparez-y les <strong>coûts uniques</strong> de la section 12.1.</li><li>Mélanie <strong>n&#39;a pas prévu de coûts annuels</strong>. Comparez les coûts annuels à ce que l&#39;entreprise paie aujourd&#39;hui pour son site (environ 300 $ par année pour Wix, selon elle), et dites-lui clairement combien elle devra prévoir chaque année.</li><li>Le <strong>total sur trois ans</strong> se donne à titre d&#39;information : c&#39;est ce que le projet coûtera vraiment.</li></ul></div><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Les hypothèses communes</strong><ul class="list-disc pl-5"><li>Studio Web FC facture <strong>75 $ de l&#39;heure</strong>.</li><li>Tous les montants sont <strong>avant taxes</strong>, le budget de Mélanie compris.</li><li>Les prix sont en <strong>dollars canadiens</strong>. Un prix en dollars américains est converti avec <strong>un seul taux pour tout le rapport</strong>, celui du jour où vous avez lu les prix, indiqué avec sa date et sa source (comme à l&#39;évaluation 1).</li><li>Le volume : environ 2 600 réservations et 9 000 participants par été (document 3 du mandat), sauf si vous justifiez une autre hypothèse.</li></ul></div><h4 id="_13-la-recommandation-finale" tabindex="-1">13. La recommandation finale <a class="header-anchor" href="#_13-la-recommandation-finale" aria-label="Permalink to &quot;13. La recommandation finale&quot;">​</a></h4><ul><li><strong>13.1 Notre recommandation.</strong> <strong>Le projet est-il faisable ?</strong> Oui, non, ou oui à certaines conditions : dites-le dans la première phrase. Puis le <strong>scénario recommandé</strong>, en une page au plus : ce qui sera en ligne le 1<sup>er</sup> mars, ce qui viendra ensuite, le coût sur trois ans.</li><li><strong>13.2 Les conditions</strong> : ce qui doit être vrai pour que ça marche.</li><li><strong>13.3 Ce que le client doit décider et faire</strong>, avec qui et avant quand : par exemple récupérer l&#39;accès au nom de domaine, choisir une politique d&#39;annulation, faire traduire la décharge par l&#39;avocat.</li></ul><h4 id="_14-references" tabindex="-1">14. Références <a class="header-anchor" href="#_14-references" aria-label="Permalink to &quot;14. Références&quot;">​</a></h4><p>Toutes les sources des deux parties, en style <a href="https://boite-outils.bib.umontreal.ca/citer/apa?p=5248896">APA 7</a>.</p><h4 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to &quot;Annexes&quot;">​</a></h4><ul><li><strong>A. Résultats des essais</strong> (évaluation 1, inchangée sauf correction).</li><li><strong>B. Déclaration d&#39;utilisation de l&#39;IA générative</strong> : gardez celle de l&#39;évaluation 1 (B.1) et ajoutez à la suite une partie <strong>B.2</strong> pour l&#39;évaluation 2.</li><li><strong>C. Contribution des membres</strong> : gardez celle de l&#39;évaluation 1 (C.1) et ajoutez à la suite une partie <strong>C.2</strong> pour l&#39;évaluation 2, signée par tous.</li><li><strong>D. Le détail de l&#39;estimation</strong>, si votre liste de tâches dépasse 15 lignes dans la section 11.</li></ul><hr><h2 id="l-intelligence-artificielle-generative" tabindex="-1">L&#39;intelligence artificielle générative <a class="header-anchor" href="#l-intelligence-artificielle-generative" aria-label="Permalink to &quot;L&#39;intelligence artificielle générative&quot;">​</a></h2><p>Les mêmes règles qu&#39;à l&#39;<a href="./evaluation-1#l-intelligence-artificielle-generative">évaluation 1</a>. En particulier, l&#39;IA générative ne doit pas <strong>produire les choix, l&#39;estimation ou le devis</strong> : ce sont les analyses que la grille évalue. Déclarez chaque usage dans l&#39;annexe B.2.</p><hr><h2 id="la-grille-d-evaluation" tabindex="-1">La grille d&#39;évaluation <a class="header-anchor" href="#la-grille-d-evaluation" aria-label="Permalink to &quot;La grille d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">Critère</th><th style="text-align:left;">Ce qui est évalué</th><th style="text-align:right;">Points</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Organisation et clarté</strong></td><td style="text-align:left;">Un seul document cohérent; résumé réécrit qui donne la recommandation, le coût et la date; tableaux lisibles; texte compréhensible pour une non-spécialiste</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Mise à jour de la partie 1</strong></td><td style="text-align:left;">Commentaires de l&#39;évaluation 1 appliqués; portée et section 7 mises à jour</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>Choix techniques</strong></td><td style="text-align:left;">Critères tirés des exigences et des contraintes; chaque choix justifié par les essais ou les sources; solutions écartées expliquées; outils qui fonctionnent ensemble, schéma à l&#39;appui</td><td style="text-align:right;">20</td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>Formats et mise en ligne</strong></td><td style="text-align:left;">Format, largeur et poids pour chaque sorte de contenu; règles d&#39;accessibilité; qui fait le travail chez le client</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>Adaptations</strong></td><td style="text-align:left;">Réponses concrètes aux contraintes déterminantes et aux risques de la zone rouge; ce qui n&#39;est pas proposé est expliqué</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Temps et échéancier</strong></td><td style="text-align:left;">Tâches complètes, estimation en trois chiffres, coussin, échéancier réaliste pour le 1<sup>er</sup> mars et ce que le client doit fournir</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Coûts sur trois ans</strong></td><td style="text-align:left;">Coûts uniques et annuels, hypothèses indiquées, comparaison au budget, trois options pour y entrer</td><td style="text-align:right;">15</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Recommandation finale</strong></td><td style="text-align:left;">Claire dès la première phrase, cohérente avec tout le rapport; conditions et décisions du client avec des dates</td><td style="text-align:right;">5</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Qualité du français</strong></td><td style="text-align:left;">Évaluée sur un extrait d&#39;environ 150 mots de la partie 2 choisi par l&#39;enseignant, selon la Politique du français de la DFCSE</td><td style="text-align:right;">10</td></tr><tr><td style="text-align:center;"></td><td style="text-align:left;"></td><td style="text-align:left;"><strong>Total</strong></td><td style="text-align:right;"><strong>100</strong></td></tr></tbody></table><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Ce qui fait perdre des points rapidement</strong><ul class="list-disc pl-5"><li>Un choix qui ne renvoie à aucune exigence, contrainte, essai ou source.</li><li>Un outil retenu malgré une limite notée dans la partie 1, sans dire comment on la contourne.</li><li>Un devis sans les coûts annuels, ou avec des dollars américains non convertis.</li><li>Un échéancier qui se termine le 28 février, sans coussin, ou qui oublie ce que le client doit fournir.</li><li>Une fonctionnalité promise qui ne figure ni dans l&#39;estimation ni dans le devis.</li><li>Une recommandation finale qui ne dit pas clairement oui ou non.</li><li>Les annexes B.2 ou C.2 manquantes, ou l&#39;annexe D absente quand la liste des tâches dépasse 15 lignes.</li></ul></div><hr><h2 id="le-calendrier-conseille" tabindex="-1">Le calendrier conseillé <a class="header-anchor" href="#le-calendrier-conseille" aria-label="Permalink to &quot;Le calendrier conseillé&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Séance</th><th style="text-align:left;">Date</th><th style="text-align:left;">Ce que vous y faites pour la proposition</th></tr></thead><tbody><tr><td style="text-align:center;">7</td><td style="text-align:left;">11 nov.</td><td style="text-align:left;">Le Lab 07 porte sur les formats et les règles de mise en ligne : ce que vous y produisez devient votre <strong>section 9</strong>. Commencez aussi la <strong>section 8</strong> (les choix techniques) en partant des tableaux de comparaison d&#39;outils de votre évaluation 1</td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;">18 nov.</td><td style="text-align:left;">La séance porte sur les critères de choix, l&#39;estimation du temps et le devis : avancez les <strong>sections 8</strong> (choix techniques), <strong>11</strong> (temps) et <strong>12</strong> (argent). Le rapport de l&#39;évaluation 1 vous est rendu corrigé</td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;">25 nov.</td><td style="text-align:left;">Rencontre avec le client : apportez <strong>dix questions</strong> (celles de votre section 7, complétées au besoin). Ses réponses confirment ou ajustent vos choix : mettez à jour les <strong>sections 7, 8 et 10</strong>. N&#39;attendez pas la rencontre pour écrire la section 8</td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;">2 déc.</td><td style="text-align:left;">15 minutes de questions sur l&#39;évaluation 2 au début de la séance. À la maison : appliquer les commentaires de l&#39;évaluation 1, écrire la section 13 et le résumé</td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;">9 déc.</td><td style="text-align:left;"><strong>Remise</strong> avant 18 h 30</td></tr></tbody></table><hr><h2 id="la-liste-de-verification-avant-la-remise" tabindex="-1">La liste de vérification avant la remise <a class="header-anchor" href="#la-liste-de-verification-avant-la-remise" aria-label="Permalink to &quot;La liste de vérification avant la remise&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Le rapport est complet, en un seul fichier : parties 1 et 2, table des matières à jour</span></label></li><li><label><input type="checkbox"><span class="check-text">La page de titre, le résumé et la portée (2.3) ont été mis à jour</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque commentaire de l&#39;évaluation 1 a été appliqué</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque choix de la section 8 renvoie à une exigence, une contrainte, un essai ou une source</span></label></li><li><label><input type="checkbox"><span class="check-text">Le schéma de la section 8.3 montre ce qui passe d&#39;un outil à l&#39;autre, et ce qui se fait à la main</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque contrainte déterminante et chaque risque rouge ont leur adaptation (section 10), qui renvoie à la mesure de la section 5.3 sans la recopier</span></label></li><li><label><input type="checkbox"><span class="check-text">Chaque fonctionnalité promise a ses heures dans l&#39;estimation et son coût dans le devis</span></label></li><li><label><input type="checkbox"><span class="check-text">L&#39;échéancier finit avant le 1<sup>er</sup> mars, avec un coussin, et dit ce que le client doit fournir et quand</span></label></li><li><label><input type="checkbox"><span class="check-text">Les coûts sont en dollars canadiens et avant taxes, avec un seul taux de change; les coûts uniques sont comparés à 8 000 $ et à 13 000 $, les coûts annuels à ce que le client paie aujourd&#39;hui</span></label></li><li><label><input type="checkbox"><span class="check-text">La première phrase de la section 13 dit si le projet est faisable</span></label></li><li><label><input type="checkbox"><span class="check-text">Le texte a été relu par une autre personne de l&#39;équipe que celle qui l&#39;a écrit, et passé dans un correcteur</span></label></li><li><label><input type="checkbox"><span class="check-text">Les annexes A, B et C sont présentes, avec les parties B.2 et C.2 pour l&#39;évaluation 2 (et l&#39;annexe D au besoin)</span></label></li><li><label><input type="checkbox"><span class="check-text">Le fichier est nommé correctement et déposé sur LÉA avant 18 h 30 le 9 décembre</span></label></li></ul>',30))])}const b=l(r,[["render",d]]);export{q as __pageData,b as default};
